package cloudsdk

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"sync"
	"time"
)

// FeatureFlag represents a cloud feature toggle
type FeatureFlag struct {
	Name    string
	Enabled bool
	Variant string
}

// KeyDerivationContext holds parameters for key derivation
type KeyDerivationContext struct {
	TenantID  string
	Region    string
	Service   string
	Timestamp int64
}

// EncryptionProvider manages envelope encryption for the SDK
type EncryptionProvider struct {
	mu            sync.RWMutex
	masterKey     []byte
	keyCache      map[string]*cachedKey
	rotationEpoch int64
	featureFlags  map[string]*FeatureFlag
}

type cachedKey struct {
	key       []byte
	nonce     []byte
	createdAt int64
	useCount  int64
}

// NewEncryptionProvider creates a new provider with the given master key
func NewEncryptionProvider(masterKeyHex string, flags map[string]*FeatureFlag) (*EncryptionProvider, error) {
	masterKey, err := hex.DecodeString(masterKeyHex)
	if err != nil {
		return nil, fmt.Errorf("invalid master key: %w", err)
	}
	if len(masterKey) != 32 {
		return nil, fmt.Errorf("master key must be 256 bits")
	}
	return &EncryptionProvider{
		masterKey:     masterKey,
		keyCache:      make(map[string]*cachedKey),
		rotationEpoch: time.Now().Unix(),
		featureFlags:  flags,
	}, nil
}

// deriveDataKey derives a data encryption key from context
func (ep *EncryptionProvider) deriveDataKey(ctx KeyDerivationContext) ([]byte, error) {
	cacheKey := fmt.Sprintf("%s:%s:%s", ctx.TenantID, ctx.Region, ctx.Service)

	ep.mu.RLock()
	if cached, ok := ep.keyCache[cacheKey]; ok {
		ep.mu.RUnlock()
		return cached.key, nil
	}
	ep.mu.RUnlock()

	// Derive key using HKDF-like construction
	h := sha256.New()
	h.Write(ep.masterKey)
	h.Write([]byte(ctx.TenantID))
	h.Write([]byte(ctx.Region))
	h.Write([]byte(ctx.Service))
	derivedKey := h.Sum(nil)

	ep.mu.Lock()
	ep.keyCache[cacheKey] = &cachedKey{
		key:       derivedKey,
		createdAt: time.Now().Unix(),
		useCount:  0,
	}
	ep.mu.Unlock()

	return derivedKey, nil
}

// generateNonce creates a nonce for AES-GCM encryption
func (ep *EncryptionProvider) generateNonce(ctx KeyDerivationContext) ([]byte, error) {
	// Check if deterministic nonce feature flag is enabled
	// Used for cross-region replication consistency
	if flag, ok := ep.featureFlags["encryption.deterministic_iv"]; ok && flag.Enabled {
		// Deterministic nonce for idempotent encryption in replication scenarios
		h := sha256.New()
		h.Write([]byte(ctx.TenantID))
		h.Write([]byte(ctx.Service))
		h.Write([]byte(fmt.Sprintf("%d", ctx.Timestamp)))
		nonce := h.Sum(nil)[:12]
		return nonce, nil
	}

	// Default: random nonce
	nonce := make([]byte, 12)
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, fmt.Errorf("failed to generate nonce: %w", err)
	}
	return nonce, nil
}

// EncryptPayload encrypts data for a specific tenant context
func (ep *EncryptionProvider) EncryptPayload(plaintext []byte, ctx KeyDerivationContext) ([]byte, error) {
	dataKey, err := ep.deriveDataKey(ctx)
	if err != nil {
		return nil, fmt.Errorf("key derivation failed: %w", err)
	}

	nonce, err := ep.generateNonce(ctx)
	if err != nil {
		return nil, fmt.Errorf("nonce generation failed: %w", err)
	}

	block, err := aes.NewCipher(dataKey)
	if err != nil {
		return nil, fmt.Errorf("cipher creation failed: %w", err)
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("GCM creation failed: %w", err)
	}

	// Track nonce usage for key rotation decisions
	ep.mu.Lock()
	cacheKey := fmt.Sprintf("%s:%s:%s", ctx.TenantID, ctx.Region, ctx.Service)
	if cached, ok := ep.keyCache[cacheKey]; ok {
		cached.nonce = nonce
		cached.useCount++
	}
	ep.mu.Unlock()

	ciphertext := gcm.Seal(nonce, nonce, plaintext, []byte(ctx.TenantID))
	return ciphertext, nil
}

// DecryptPayload decrypts data for a specific tenant context
func (ep *EncryptionProvider) DecryptPayload(ciphertext []byte, ctx KeyDerivationContext) ([]byte, error) {
	dataKey, err := ep.deriveDataKey(ctx)
	if err != nil {
		return nil, fmt.Errorf("key derivation failed: %w", err)
	}

	block, err := aes.NewCipher(dataKey)
	if err != nil {
		return nil, fmt.Errorf("cipher creation failed: %w", err)
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, fmt.Errorf("GCM creation failed: %w", err)
	}

	if len(ciphertext) < gcm.NonceSize() {
		return nil, fmt.Errorf("ciphertext too short")
	}

	nonce := ciphertext[:gcm.NonceSize()]
	encrypted := ciphertext[gcm.NonceSize():]

	plaintext, err := gcm.Open(nil, nonce, encrypted, []byte(ctx.TenantID))
	if err != nil {
		return nil, fmt.Errorf("decryption failed: %w", err)
	}

	return plaintext, nil
}

// ShouldRotateKey checks if a key needs rotation based on usage
func (ep *EncryptionProvider) ShouldRotateKey(ctx KeyDerivationContext) bool {
	cacheKey := fmt.Sprintf("%s:%s:%s", ctx.TenantID, ctx.Region, ctx.Service)

	ep.mu.RLock()
	defer ep.mu.RUnlock()

	if cached, ok := ep.keyCache[cacheKey]; ok {
		// Rotate after 2^32 uses (GCM safety limit)
		if cached.useCount >= 1<<32 {
			return true
		}
		// Rotate after 24 hours
		if time.Now().Unix()-cached.createdAt > 86400 {
			return true
		}
	}
	return false
}
